python3 -c "
import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
# Find page breaks (form feeds)
pages = text.split('\f')
for i, page in enumerate(pages):
    if 'Limitations' in page and i < 15:
        # find the line
        for line in page.split('\n'):
            if 'Limitations' in line and 'Appendix' not in line.lower():
                print(f'Page {i+1}: {line.strip()[:80]}')
    if 'References' in page and i < 15:
        for line in page.split('\n'):
            if line.strip().startswith('References'):
                print(f'Page {i+1}: {line.strip()[:80]}')
    if i < 15 and ('Prompt Templates' in page or 'appendix' in page.lower()[:100]):
        for line in page.split('\n'):
            if 'Prompt Templates' in line:
                print(f'Page {i+1}: {line.strip()[:80]}')
"

